// src/pages/VotesPage.tsx
// Página de votações - MVP funcional

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useActiveActor } from '../contexts/ActiveActorContext';
import { listVotes, getVote, vote, publishVote, closeVote, type Vote } from '../api/votes';
import './VotesPage.css';

export default function VotesPage() {
  const navigate = useNavigate();
  const { activeActor } = useActiveActor();
  const [votes, setVotes] = useState<Vote[]>([]);
  const [selectedVote, setSelectedVote] = useState<Vote | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'active' | 'closed'>('all');
  const [isVoting, setIsVoting] = useState(false);

  useEffect(() => {
    loadVotes();
  }, [filter]);

  const loadVotes = async () => {
    try {
      setIsLoading(true);
      const response = await listVotes({
        status: filter === 'all' ? undefined : filter,
        limit: 50,
      });
      setVotes(response.votes);
    } catch (error) {
      console.error('Erro ao carregar votações:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleVoteClick = async (voteId: string) => {
    try {
      const voteData = await getVote(voteId);
      setSelectedVote(voteData);
    } catch (error) {
      console.error('Erro ao carregar votação:', error);
    }
  };

  const handleVote = async (optionId: string) => {
    if (!selectedVote || isVoting) return;

    try {
      setIsVoting(true);
      await vote(selectedVote.vote_id, optionId);
      // Recarregar votação atualizada
      const updatedVote = await getVote(selectedVote.vote_id);
      setSelectedVote(updatedVote);
      // Atualizar lista
      await loadVotes();
    } catch (error: any) {
      alert(error.message || 'Erro ao votar');
    } finally {
      setIsVoting(false);
    }
  };

  const handlePublish = async (voteId: string) => {
    try {
      await publishVote(voteId);
      await loadVotes();
      if (selectedVote?.vote_id === voteId) {
        const updated = await getVote(voteId);
        setSelectedVote(updated);
      }
    } catch (error: any) {
      alert(error.message || 'Erro ao publicar votação');
    }
  };

  const handleClose = async (voteId: string) => {
    try {
      await closeVote(voteId);
      await loadVotes();
      if (selectedVote?.vote_id === voteId) {
        const updated = await getVote(voteId);
        setSelectedVote(updated);
      }
    } catch (error: any) {
      alert(error.message || 'Erro ao encerrar votação');
    }
  };

  if (selectedVote) {
    return (
      <div className="votes-page">
        <div className="votes-container">
          <button
            className="votes-back-button"
            onClick={() => setSelectedVote(null)}
          >
            ← Voltar
          </button>

          <div className="vote-detail">
            <div className="vote-detail-header">
              <h1 className="vote-detail-title">{selectedVote.title}</h1>
              <span className={`vote-status vote-status-${selectedVote.status}`}>
                {selectedVote.status === 'draft' && 'Rascunho'}
                {selectedVote.status === 'active' && 'Ativa'}
                {selectedVote.status === 'closed' && 'Encerrada'}
              </span>
            </div>

            {selectedVote.description && (
              <p className="vote-detail-description">{selectedVote.description}</p>
            )}

            <div className="vote-options">
              {selectedVote.options.map((option) => {
                const result = selectedVote.results?.find((r) => r.option_id === option.option_id);
                // const isSelected = selectedVote.has_voted && result;

                return (
                  <div key={option.option_id} className="vote-option">
                    {selectedVote.status === 'active' && !selectedVote.has_voted && (
                      <button
                        className="vote-option-button"
                        onClick={() => handleVote(option.option_id)}
                        disabled={isVoting}
                      >
                        {option.label}
                      </button>
                    )}

                    {(selectedVote.status === 'closed' || selectedVote.has_voted) && result && (
                      <div className="vote-option-result">
                        <div className="vote-option-header">
                          <span className="vote-option-label">{option.label}</span>
                          <span className="vote-option-stats">
                            {result.count} votos ({result.percentage.toFixed(1)}%)
                          </span>
                        </div>
                        <div className="vote-option-bar">
                          <div
                            className="vote-option-bar-fill"
                            style={{ width: `${result.percentage}%` }}
                          />
                        </div>
                      </div>
                    )}

                    {selectedVote.status === 'draft' && (
                      <div className="vote-option-draft">{option.label}</div>
                    )}
                  </div>
                );
              })}
            </div>

            {selectedVote.total_votes !== undefined && (
              <div className="vote-total">
                Total de votos: {selectedVote.total_votes}
              </div>
            )}

            {activeActor?.actor_id === selectedVote.created_by_actor_id && (
              <div className="vote-actions">
                {selectedVote.status === 'draft' && (
                  <button
                    className="vote-action-button vote-action-publish"
                    onClick={() => handlePublish(selectedVote.vote_id)}
                  >
                    Publicar Votação
                  </button>
                )}
                {selectedVote.status === 'active' && (
                  <button
                    className="vote-action-button vote-action-close"
                    onClick={() => handleClose(selectedVote.vote_id)}
                  >
                    Encerrar Votação
                  </button>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="votes-page">
      <div className="votes-container">
        <div className="votes-header">
          <h1 className="votes-title">Votações</h1>
          <button
            className="votes-create-button"
            onClick={() => navigate('/votes/create')}
          >
            + Criar Votação
          </button>
        </div>

        <div className="votes-filters">
          <button
            className={`votes-filter ${filter === 'all' ? 'active' : ''}`}
            onClick={() => setFilter('all')}
          >
            Todas
          </button>
          <button
            className={`votes-filter ${filter === 'active' ? 'active' : ''}`}
            onClick={() => setFilter('active')}
          >
            Ativas
          </button>
          <button
            className={`votes-filter ${filter === 'closed' ? 'active' : ''}`}
            onClick={() => setFilter('closed')}
          >
            Encerradas
          </button>
        </div>

        {isLoading ? (
          <div className="votes-loading">Carregando...</div>
        ) : votes.length === 0 ? (
          <div className="votes-empty">
            Nenhuma votação encontrada.
          </div>
        ) : (
          <div className="votes-list">
            {votes.map((v) => (
              <div
                key={v.vote_id}
                className="votes-item"
                onClick={() => handleVoteClick(v.vote_id)}
              >
                <div className="votes-item-header">
                  <h3 className="votes-item-title">{v.title}</h3>
                  <span className={`vote-status vote-status-${v.status}`}>
                    {v.status === 'draft' && 'Rascunho'}
                    {v.status === 'active' && 'Ativa'}
                    {v.status === 'closed' && 'Encerrada'}
                  </span>
                </div>
                {v.description && (
                  <p className="votes-item-description">{v.description}</p>
                )}
                <div className="votes-item-footer">
                  <span className="votes-item-date">
                    {new Date(v.created_at).toLocaleDateString('pt-BR')}
                  </span>
                  {v.total_votes !== undefined && (
                    <span className="votes-item-votes">
                      {v.total_votes} votos
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}








